transforms.example:
fields:
  - { name: total, value: "{{ record.price * record.quantity }}" }
  - { name: label, value: "{{ upper(record.name) }}: {{ record.total }}" }

fields:
  - { name: source, value: runnel }
  - { name: batch, value: "{{ params.BATCH }}" }

fields:
  - { name: kdnr, type: int }
  - { name: umsatz, type: decimal, format: "#.##0,00" }

groupBy: [Datum]
aggregates:
  - { name: orders, function: count }
  - { name: total, function: sum, field: Betrag }

field: status
target: statusText
values:
  - { from: A, to: Active }
  - { from: I, to: Inactive }
default: Unknown

fields:
  - { name: kdnr, rename: externalId }
  - { name: name }
# or instead of fields:
# remove: [telefon]

fields:
  - { name: total, descending: true }
  - { name: name, ignoreCase: true }

cases:
  - { when: "{{ record.umsatz >= 10000 }}", to: key-accounts }
  - { when: "{{ record.umsatz > 0 }}", to: standard }
default: others

path: data/orders.csv
delimiter: ";"
fields:
  - { name: Nr, type: int }
  - { name: Betrag, type: decimal, format: "#.##0,00" }

path: out/orders.csv
fields:
  - { name: Datum, format: dd.MM.yyyy }
  - { name: Betrag, format: "#.##0,00" }

path: data/orders.json
records: data.items
fields:
  - { name: id, type: int }
  - { name: city, from: address.city }

path: out/orders.json
fields:
  - { name: id }
  - { name: day, format: dd.MM.yyyy }
